#!/usr/bin/env tsx
/**
 * Generate Top-Level Route Loaders
 *
 * `src/app.ts` imports every command, so loading it runs every command
 * module and what each one imports. `src/app-for-args.ts` loads only the
 * top-level route being run instead, through the `import()` this script
 * writes for each route in `app.ts`. It reads the route map and the imports
 * from `app.ts` itself, so adding a command there is all it takes.
 *
 * The output is gitignored and regenerated by `generate:docs`, which runs as
 * part of `dev`, `build`, `bundle`, `typecheck`, and `test`.
 *
 * Usage:   tsx script/generate-route-loaders.ts
 * Output:  src/generated/route-loaders.ts
 */

import { mkdirSync } from "node:fs";
import { readFile, writeFile } from "node:fs/promises";
import ts from "typescript";

const APP_PATH = "src/app.ts";
const OUTPUT_PATH = "src/generated/route-loaders.ts";

/** The call in `app.ts` that builds the top-level route map. */
const ROUTES_BUILDER = "buildSentryRoutes";

/** Where a local name in `app.ts` was imported from. */
type ImportedName = { module: string; exportName: string };

function fail(message: string): never {
  throw new Error(`${APP_PATH}: ${message}`);
}

/** Map each name `app.ts` imports to its module and exported name. */
function collectImports(file: ts.SourceFile): Map<string, ImportedName> {
  const imports = new Map<string, ImportedName>();
  for (const statement of file.statements) {
    if (
      !(
        ts.isImportDeclaration(statement) &&
        ts.isStringLiteral(statement.moduleSpecifier)
      )
    ) {
      continue;
    }
    const bindings = statement.importClause?.namedBindings;
    if (!(bindings && ts.isNamedImports(bindings))) {
      continue;
    }
    for (const element of bindings.elements) {
      imports.set(element.name.text, {
        module: statement.moduleSpecifier.text,
        exportName: (element.propertyName ?? element.name).text,
      });
    }
  }
  return imports;
}

/** The object literal passed to {@link ROUTES_BUILDER} in `app.ts`. */
function findRoutesLiteral(file: ts.SourceFile): ts.ObjectLiteralExpression {
  let found: ts.ObjectLiteralExpression | undefined;
  const visit = (node: ts.Node): void => {
    if (
      ts.isCallExpression(node) &&
      ts.isIdentifier(node.expression) &&
      node.expression.text === ROUTES_BUILDER
    ) {
      const [argument] = node.arguments;
      if (!(argument && ts.isObjectLiteralExpression(argument))) {
        fail(`${ROUTES_BUILDER}() must get an object literal`);
      }
      found = argument;
      return;
    }
    ts.forEachChild(node, visit);
  };
  visit(file);
  return found ?? fail(`no ${ROUTES_BUILDER}() call`);
}

function routeName(property: ts.ObjectLiteralElementLike): string {
  const { name } = property;
  if (name && (ts.isIdentifier(name) || ts.isStringLiteral(name))) {
    return name.text;
  }
  return fail(`unsupported route key ${property.getText()}`);
}

/** The local name a route is set to, for `name: value` and `{ name }`. */
function routeValue(property: ts.ObjectLiteralElementLike): string {
  if (ts.isShorthandPropertyAssignment(property)) {
    return property.name.text;
  }
  if (
    ts.isPropertyAssignment(property) &&
    ts.isIdentifier(property.initializer)
  ) {
    return property.initializer.text;
  }
  return fail(
    `route ${property.getText()} must be set to an imported name, so it can be loaded on its own`,
  );
}

const source = await readFile(APP_PATH, "utf8");
const file = ts.createSourceFile(APP_PATH, source, ts.ScriptTarget.Latest);
const imports = collectImports(file);

const loaders = findRoutesLiteral(file).properties.map((property) => {
  const name = routeName(property);
  const value = routeValue(property);
  const imported =
    imports.get(value) ??
    fail(`route "${name}" is set to ${value}, which is not imported`);
  // `app.ts` is in `src/`, the output in `src/generated/`
  const module = imported.module.replace(/^\.\//, "../");
  return `  ${JSON.stringify(name)}: () =>\n    import(${JSON.stringify(module)}).then((m) => m.${imported.exportName}),`;
});

const output = `// Generated by script/generate-route-loaders.ts from src/app.ts. Do not edit.

import type { SentryRoutes } from "../app-root.js";

/** Loads one top-level route of \`src/app.ts\`. */
type RouteLoader = () => Promise<SentryRoutes[string]>;

/** A loader for each top-level route of \`src/app.ts\`, in its order. */
export const ROUTE_LOADERS: Readonly<Record<string, RouteLoader>> = {
${loaders.join("\n")}
};
`;

mkdirSync("src/generated", { recursive: true });
await writeFile(OUTPUT_PATH, output, "utf8");
process.stdout.write(`Wrote ${OUTPUT_PATH} (${loaders.length} routes)\n`);
